import{z as i,x as d,o as r,c as p,q as l,j as t,D as E,d as e,s as A,S as n,b as o}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"标量替换 SROA","description":"","frontmatter":{"title":"标量替换 SROA","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sroa.md","filePath":"cs/sroa.md","lastUpdated":1791413859000}'),c={name:"cs/sroa.md"};function S(B,a,C,m,u,h){const s=d("Mermaid");return r(),p("div",null,[a[2]||(a[2]=l('<h1 id="标量替换-sroa" tabindex="-1">标量替换 SROA <a class="header-anchor" href="#标量替换-sroa" aria-label="Permalink to &quot;标量替换 SROA&quot;">​</a></h1><div class="epigraph"><p>把不逃逸的结构体或数组拆成成员标量，用 SSA 名代替内存槽，使后续传播与分配看见寄存器，而不是 load/store。</p><footer>—— 据 Cytron 等标量替换思想；LLVM SROA；Appel 对聚合的讨论整理</footer></div><p>上一课<a href="/cs/escape-analysis">逃逸分析</a>标出未逃逸对象。缺口是<strong>拆开</strong>：<code>struct {int a,b;}</code> 的 <code>p.a</code> 不应经过栈槽。SROA（scalar replacement of aggregates）：按偏移切成元素，能提升则变 <code>alloca</code> 上的 SSA。本课钉切分条件，不写完整 mem2reg 与 φ 插入——SSA 构造课已给。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对 <code>alloca</code>：若只被常量偏移的 load/store 访问、无变长索引、指针不逃逸，则每个槽一个名。数组常下标则整数组可能无法拆。选择：拆字段，留无法拆的部分在内存。</p><h3 id="sroa-不是寄存器分配" tabindex="-1">SROA 不是寄存器分配 <a class="header-anchor" href="#sroa-不是寄存器分配" aria-label="Permalink to &quot;SROA 不是寄存器分配&quot;">​</a></h3><p>拆完是虚拟寄存器；着色后课。不要声称 SROA 已选物理寄存器。</p><p><span class="marginnote">LLVM 的 SROA/mem2reg 是工程标准名。Muchnick 有标量替换。与 SSA 构造紧密：提升后的名要插 φ。</span></p><p><span class="marginnote">直觉类比：SROA 像把整箱行李拆成几件手提——原本要「开箱取物」（load/store）的东西，现在各拿各的（寄存器名）；只有塞不进手提限量的件（变下标、逃逸）才留在箱里。</span></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>聚合在 IR 里常是内存，阻塞 GVN 与常量传播。提升后 <code>s.a=1; use(s.a)</code> 变成常量。缺口是<strong>可拆形状</strong>，不是逃逸分类本身。</p>',11)),(r(),t(n,null,{default:E(()=>[A(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20AGG%5B%22alloca%20%E8%81%9A%E5%90%88%22%5D%20--%3E%20SPLIT%5B%22%E6%8C%89%E5%AD%97%E6%AE%B5%E5%88%87%E5%BC%80%22%5D%0A%20%20SPLIT%20--%3E%20SSA%5B%22%E6%8F%90%E5%8D%87%E4%B8%BA%20SSA%20%E5%90%8D%22%5D%0A%20%20SSA%20--%3E%20OPT%5B%22%E4%BC%A0%E6%92%AD%20%2F%20DCE%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("p",null,"与 ABI：参数结构体可能 already 在寄存器；SROA 处理的是局部槽。返回结构体由调用约定课再谈。",-1)),a[4]||(a[4]=o("h2",{id:"机制",tabindex:"-1"},[e("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=o("p",null,[e("选择字段：union、指针算术、可变下标使切分失败。必须保守留内存。不要拆 "),o("code",null,"volatile"),e(" 槽。")],-1)),(r(),t(n,null,{default:E(()=>[A(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E4%B8%80%E4%B8%AA%20alloca%20%E6%A7%BD%22%5D%20--%3E%20Q%7B%22%E6%8C%87%E9%92%88%E6%98%AF%E5%90%A6%E9%80%83%E9%80%B8%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E9%80%83%E9%80%B8%22%7C%20KEEP%5B%22%E6%95%B4%E6%A7%BD%E7%95%99%E5%86%85%E5%AD%98%22%5D%0A%20%20Q%20--%3E%7C%22%E6%9C%AA%E9%80%83%E9%80%B8%22%7C%20Q2%7B%22%E8%AE%BF%E9%97%AE%E9%83%BD%E6%98%AF%E5%B8%B8%E9%87%8F%E5%81%8F%E7%A7%BB%EF%BC%9F%22%7D%0A%20%20Q2%20--%3E%7C%22%E6%9C%89%E6%8C%87%E9%92%88%E7%AE%97%E6%9C%AF%2F%E5%8F%98%E4%B8%8B%E6%A0%87%22%7C%20KEEP%0A%20%20Q2%20--%3E%7C%22%E6%98%AF%22%7C%20Q3%7B%22volatile%EF%BC%9Funion%EF%BC%9F%22%7D%0A%20%20Q3%20--%3E%7C%22%E6%98%AF%22%7C%20KEEP%0A%20%20Q3%20--%3E%7C%22%E5%90%A6%22%7C%20SPLIT%5B%22%E6%8C%89%E5%81%8F%E7%A7%BB%E5%88%87%E6%88%90%E6%88%90%E5%91%98%E6%A0%87%E9%87%8F%3Cbr%2F%3E%E6%8F%90%E5%8D%87%E4%B8%BA%20SSA%20%E5%90%8D%22%5D%0A%20%20SPLIT%20--%3E%20WIN%5B%22%E5%B8%B8%E9%87%8F%E4%BC%A0%E6%92%AD%E4%B8%8E%20DCE%20%E6%9C%89%E4%BA%86%E7%9D%80%E5%8A%9B%E7%82%B9%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p>内联后新 <code>alloca</code> 是 SROA 的主要客户——与内联顺序绑在一起。</p><p><span class="marginnote">数字实例：<code>struct {int a, b;}</code> 占 8 字节，SROA 把它切成两个 4 字节的 SSA 名。写 <code>s.a = 1; use(s.a)</code> 后传播直接把 use 换成常量 1，两次 load/store 全部消失——这就是「让优化器看见标量」的直接收益。</span></p><p><span class="marginnote">常见误区：初学者容易以为拆完就进了物理寄存器。SROA 只是把内存槽换成虚拟寄存器（SSA 名），至于这些名最终落在哪几个真实寄存器、哪些溢出到栈，是后面的寄存器分配课的事。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Cytron φ 放置。后课默认：未逃逸聚合可标量化。PRE 一类部分冗余消除在标量 IR 上更有效。下一课<a href="/cs/pgo">PGO</a>：热度告诉内联与展开往哪使劲。</p><p>也不把 SROA 当对象布局 ABI 的改变（公开结构体布局仍由语言定）。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SROA：未逃逸聚合 → 成员标量 SSA。</li><li>变下标、逃逸、volatile 阻止拆分。</li><li>为传播与分配打开门，本身不着色。</li><li>出处：LLVM SROA；对照 Cytron SSA、Appel、Muchnick。</li></ul>',8))])}const F=i(c,[["render",S]]);export{f as __pageData,F as default};
